import six
from ute_common_util.generic.timeout import Timeout
from .exception import EmptyResult


class ExecutionResult(object):
    def __init__(self):
        self.__empty = True
        self._result = None
        self._exc_info = None

    def get(self, timeout=0):
        """Returns execution result data or raises exception in case of execution error."""
        if timeout > 0:
            self._wait_for_result(timeout)
        return self._get_result()

    def put(self, result=None, exc_info=None):
        """Save provided data.

        :param result: Some result to store.
        :param exc_info: sys.exc_info() in case of exception.
        """
        self.__empty = False
        self._result = result
        self._exc_info = exc_info

    def _get_result(self):
        if self._exc_info:
            six.reraise(*self._exc_info)
        return self._result

    def _wait_for_result(self, timeout):
        timeout_timer = Timeout(timeout)
        while timeout_timer.is_not_reached():
            if not self.__empty:
                return
        raise EmptyResult("Result is not available after {} seconds".format(timeout))
